<?php

declare(strict_types=1);

namespace App\Support;

/**
 * Symmetric encryption for small secrets stored in the database (two-step
 * sign-in secrets), so a copy of the database alone doesn't hand over
 * everyone's authenticator seed. libsodium secretbox (XSalsa20-Poly1305:
 * authenticated, a tampered value fails to decrypt rather than decrypting
 * to garbage).
 *
 * The key is APP_KEY in .env ("base64:" + 32 random bytes), generated by
 * deploy/install.sh. Losing or changing it makes stored secrets unreadable —
 * people would have to set two-step sign-in up again.
 */
final class Crypto
{
    /** Encrypt with the APP_KEY (libsodium secretbox, random nonce); returns a "v1:"-prefixed base64 string. */
    public static function encrypt(string $plaintext): string
    {
        $nonce = random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);
        return 'v1:' . base64_encode($nonce . sodium_crypto_secretbox($plaintext, $nonce, self::key()));
    }

    /** @throws \RuntimeException if the value is malformed, tampered with, or encrypted under another key */
    public static function decrypt(string $stored): string
    {
        if (!str_starts_with($stored, 'v1:')) {
            throw new \RuntimeException('Unrecognised encrypted value.');
        }
        $raw = base64_decode(substr($stored, 3), true);
        if ($raw === false || strlen($raw) <= SODIUM_CRYPTO_SECRETBOX_NONCEBYTES) {
            throw new \RuntimeException('Malformed encrypted value.');
        }
        $plain = sodium_crypto_secretbox_open(
            substr($raw, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),
            substr($raw, 0, SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),
            self::key()
        );
        if ($plain === false) {
            throw new \RuntimeException('Could not decrypt (wrong APP_KEY or tampered value).');
        }
        return $plain;
    }

    /** Whether APP_KEY is configured, so callers can disable features that need encryption instead of throwing. */
    public static function available(): bool
    {
        try {
            self::key();
            return true;
        } catch (\RuntimeException) {
            return false;
        }
    }

    private static function key(): string
    {
        $configured = (string) Config::get('app.key', '');
        $key = str_starts_with($configured, 'base64:') ? base64_decode(substr($configured, 7), true) : false;
        if ($key === false || strlen($key) !== SODIUM_CRYPTO_SECRETBOX_KEYBYTES) {
            throw new \RuntimeException('APP_KEY is missing or invalid in .env — run deploy/install.sh to generate one.');
        }
        return $key;
    }
}
